import { Router } from 'express';
import * as supplierController from '@/controllers/supplierController';
import { authenticateToken } from '@/middlewares/authMiddleware';
import { formRequest } from '@/middlewares/formRequest';
import { StoreSupplierRequest } from '@/requests/supplier/StoreSupplierRequest';
import { UpdateSupplierRequest } from '@/requests/supplier/UpdateSupplierRequest';
const router = Router();
router.post('/', authenticateToken, formRequest(StoreSupplierRequest), supplierController.createSupplier);
router.get('/', authenticateToken, supplierController.getAllSupplier);
router.get('/:id', authenticateToken, supplierController.getSupplierById);
router.put('/:id', authenticateToken, formRequest(UpdateSupplierRequest), supplierController.updateSupplier);
router.delete('/:id', authenticateToken, supplierController.deleteSupplier);
export default router;
